package parser

import "strings"

// Fields splits a CSV line. Rewritten to avoid strings.Split allocations.
func Fields(line string) []string {
	out := make([]string, 0, strings.Count(line, ",")+1)
	start := 0
	for i := 0; i < len(line); i++ {
		if line[i] == ',' {
			out = append(out, line[start:i])
			start = i + 1
		}
	}
	return append(out, line[start:])
}
package migrate

import (
	"database/sql"
	"fmt"
)

// Run adds the orders.status column and backfills it.
func Run(db *sql.DB) error {
	if _, err := db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`); err != nil {
		return fmt.Errorf("add column: %w", err)
	}
	rows, err := db.Query(`SELECT id FROM orders`)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			return err
		}
		if _, err := db.Exec(`INSERT INTO order_events (order_id, kind) VALUES (?, 'backfilled')`, id); err != nil {
			return err
		}
		if _, err := db.Exec(`UPDATE orders SET status = 'open' WHERE id = ?`, id); err != nil {
			return err
		}
	}
	return rows.Err()
}
package users

import "errors"

type User struct {
	ID    int
	Email string
}

var db = map[int]User{1: {1, "a@x.io"}, 2: {2, "b@x.io"}}

// GetUser returns the zero User when not found.
func GetUser(id int) User { return db[id] }

// FetchUser replaces GetUser: it reports missing users explicitly.
func FetchUser(id int) (User, error) {
	u, ok := db[id]
	if !ok {
		return User{}, errors.New("user not found")
	}
	return u, nil
}
package users

func AdminEmail() string { return GetUser(1).Email }
